Modify the code below to print the 10th and 11th prime numbers in ascending order. The code should also check if the 10th and 11th prime numbers are consecutive, and print a message stating whether they are consecutive or not.

```python
def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def get_primes(n):
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes

primes = get_primes(20)
if primes[9] == primes[10] - 1:
    print(primes[9], primes[10], "are consecutive prime numbers.")
else:
    print(primes[9], primes[10], "are not consecutive prime numbers.")
